WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (58::BIGINT, 'La profe es buena en general, califica un poco rudo pero se nota que le gusta ayudar a los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Brinda apoyo']::TEXT[], '2026-02-11T00:00:00+00:00'::TIMESTAMPTZ, '460b43efbe3a0f4ffcd3939bc3659b97a95dc80d0656c8460ebb54fc66dca63b'::TEXT, ARRAY[965]::BIGINT[]),
    (58::BIGINT, 'Si tienen la oportunidad de matricular con otr@s profes, háganlo. No es clara con lo que pide en las tareas o proyectos, tarda en dar retroalimentación, muy poco responde los correos que se le envían, hace exámenes largos con poco tiempo, así mismo las tareas, y da las calificaciones hasta el final.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '97385ccc6426e2c355c4d942de4de261bbe7d3e236f9eb4da228135a4b8bb594'::TEXT, ARRAY[92, 2366]::BIGINT[]),
    (58::BIGINT, 'El curso es muy fácil, pero prácticamente todo se hace en grupo y se necesitan buenos compañeros o se va a complicar. La profesora complica el curso más de lo que debería.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2823049de74c03dbf46c95c2acd5c4600bdd4684bde8495422668c09c164b3a6'::TEXT, ARRAY[965]::BIGINT[]),
    (58::BIGINT, 'La peor "profesora" solo se sienta a leer power points de una materia que se aprende en excel (los cuales ni si quiera hace ella) y a pesar de eso en el mismo examen pone mal cosas que estan exactamente igual que la presentacion. no tiene vocacion, los examenes son dificiles.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2023-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'ec04404b2a959125903e3d801193054d66045e10b16b3f2db5d7955c0b9ac21e'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'Fácilmente, la peor profesora que he tenido en lo que llevo de carrera: ve los correos, pero no responde; dura mucho en revisar los trabajos; las explicaciones son demasiado confusas, al igual que el material de apoyo. Cero vocación para enseñar. No es fácil pasar y difícilmente se aprende algo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'eeef44d5ea15dac1fdbdb6368b2b893f92f3c8149343d60590e35f58f1f188f1'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'La explicación en sus clases son totalmente enredadas, el material que utiliza es de otros profesores y presenta muchos errores que al final no los corrige. Durante los exámenes no sabe como se hacen las cosas y cuando uno le hace una consulta se contradice a lo que había enseñado.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '3ccbc2ceb25d69584ba920fe426ce8ab1471f6792f0e2a0c0be4868e516073f8'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'Las clases que da no son claras, todo el material de estudio que ofrece es de otros profesores y tiene muchos errores, además realiza prácticas que no son claras, no sube las soluciones hasta un día antes del examen y los exámenes son súper complicados y diferentes a las prácticas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1584b18e977f7436009bd4e64b3fd07847bee1affd71a033c82e2fb2194f2e9a'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'No matriculen con esta profe. No hace su propio material de clases por lo que se confunde en sus propias explicaciones, evalúa completamente diferente a lo que enseña en clases, no responde correos y practicamente hay que rogar para que suba las soluciones de las prácticas'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5f236e8851a052714c881f7d8b1023af6806c1cfe3c93d0d70e96509a1c62188'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'No matriculen con ella, es demasiada mala ,no sabe cómo dar la clase, literal es demasiada mala'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-09-20T00:00:00+00:00'::TIMESTAMPTZ, '7f8547bb2cc49cffbcb2139c03a3b11616f55fbbaffd14205f20503cd8793f13'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'No da la clase de forma clara y los trabajos son confusos y las practicas.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-08-23T00:00:00+00:00'::TIMESTAMPTZ, '73f396b417c64bb05154237c62add9f824aa1079bab3eb25856decd9302a146f'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'No se matriculen con esta profe, es una pesima profesora, debe ver retroalimentacion en youtube, no se preocupa por sus estudiantes la manera que maneja la. Clase no tiene sentido, cree que con los pdf es suficientes, explica muy mal hace enredos, no matriculen con ella no pierdan el tiempo,'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, 'd8235f5f333ab240713d498b17043bdb53f5cabd46b970391fcadd00b54f13f5'::TEXT, ARRAY[2366]::BIGINT[]),
    (58::BIGINT, 'Si estuvo en un tecnico este curso es hacer un Expojoven universitario, por lo que ojala le toque un buen grupo de trabajo ya que hay que dedicar muchas horas de investigacion y analisis porque es super exigente, dura demasiado calificando. Consejo, si se quiere y no lo necesita no lo meta'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '3229f3facccee2c668d922a8a1193b28bba5922e5090f92b2ecb88d039f385c5'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'Super mala, dura mucho calificando. Revisa como si estuviera calificando tesis final y es muy desordenada. Van a perder el curso y darse cuenta hasta en semana 18 cuando da las notas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3aab25d36786610aa251726cecccd9fb693fbde06d30b5aaa1d4d046cf99fee5'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'Con creces, la peor experiencia en clases que he tenido en 4 años en el Tecnológico. Poco mas que decir, si matricula con ella que sea por pura necesidad de créditos; de otro modo hágase un favor y lleve el curso en otro momento o con otro profe.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-05-27T00:00:00+00:00'::TIMESTAMPTZ, '8f81840c78469f6c69d8c0fe6f5a29ddc9a2de88b4afa460dc5a437c423ad0f8'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'NO MATRICULE CON ELLA. Pesima profe, no tiene interes alguno, deja tareas casi todas las semanas y de temas que no se saben de donde los saca. No explica nada, solo lee las presentaciones, no hay rubricas claras, casi ni aparece y cuando lo hace es pesima, el curso es una expojoven sin sentido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-05-19T00:00:00+00:00'::TIMESTAMPTZ, '86825d447dfeab51d229aedf032b8f0c3b896c0d34287bee506f472e2b91b2c2'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'Prepárense para leer y buscar retroalimentación en youtube, es pésima profesora, no le importan sus estudiantes, piensa que con los pdf es suficiente para aprender(claramente no).DE VERDAD HÁGANSE UN FAVOR Y NO PIERDAN EL TIEMPO EN CLASES QUE NO LES BENEFICIA, en fin no matriculen con ella'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-04-18T00:00:00+00:00'::TIMESTAMPTZ, 'c9eb0a08e1e2be66ecdbf7c954d4e01f4fbc8252e9cb8008550242150fbfca3a'::TEXT, ARRAY[267]::BIGINT[]),
    (58::BIGINT, 'POR FAVOR ¡NO MATRICULEN CON ELLA! Es una pésima profesora, súper desinteresada por el estudiante, deja prácticas y tareas sin haber explicado el tema, desorganizada al máximo y da las clases para salir de la obligación solo porque le pagan. Háganse un bien y no matriculen con ella'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-04-08T00:00:00+00:00'::TIMESTAMPTZ, 'f4035700cdc3c04af2eca64f0a916ad433c27c0b5cc7a7816f72be789eb88a58'::TEXT, ARRAY[267]::BIGINT[]),
    (58::BIGINT, 'La profe se atrasa revisando practicas y proyecto, al final nada más entrega notas y nunca se sabe de donde salieron. Muchos trabajos en grupo. No la recomiendo, sin embargo, al final se pasa el curso.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-01-12T00:00:00+00:00'::TIMESTAMPTZ, '82552e00cdea29257974c0385cbf3d3376901937251cee88287e75f502b9c469'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'No explica nada bien, sólo pasa presentaciones que ni están bien diagramadas, por lo menos al final no califica tan duro'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'bed1ae1a29674d29a3859db1dd3e3d9a48483afa41f087f812acb8a7216da62b'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'Eventualmente (Si ya llevó el curso entenderá) La mae no explica las fórmulas, solo lee la presentación y la sube para que uno vea como resuelve las hps practicas de 30 preguntas que manda'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2020-10-04T00:00:00+00:00'::TIMESTAMPTZ, '0467d7a861618da0c27215019191fd1924afe63e78e8f3ef6814894ed10b728b'::TEXT, ARRAY[92]::BIGINT[]),
    (58::BIGINT, 'Es toda bipolar la doña, además, no es tan buena profe.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-01-26T00:00:00+00:00'::TIMESTAMPTZ, '90c8b88729d76bf39a76d72776f697234f0f251c983bc31328a203a1de6f7972'::TEXT, ARRAY[965]::BIGINT[]),
    (58::BIGINT, 'Desorganizada. No lleva al día las evaluaciones por lo que a final de semestre te pone cero en algunas.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '64f77c04a9f4de4646d5d52a3b2a8fc4bb3be5049363929e68deee645e3823ea'::TEXT, ARRAY[965]::BIGINT[]),
    (58::BIGINT, 'Es una hp. Super desorganizada y las notas son muy impredecibles, no la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '47d63a2b32cacc5c68d73046b273e1d6283bdea16aa9f0099fae049aa795fc6c'::TEXT, ARRAY[965]::BIGINT[]),
    (58::BIGINT, 'No se de donde se saca las notas, pero pasa a todos para evitar problemas... Si es bien sapo con ella pasa con una nota alta.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2dd57b97bbb1342e8ffa8c7bc7a33d3973e8e7fca76d977f351b36a6a0872926'::TEXT, ARRAY[965]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
